INSERT INTO projects (id, slug, name, tagline, description, category, status, live_url, github_url, tech_stack, action_button_label, action_button_url, cover_image_url, stats_json, is_published, featured_order) VALUES
('proj-01', 'hyperion', 'Hyperion', 'Ultra-low-latency event streaming engine written in pure Rust. Built on lock-free memory ring buffers and Linux io_uring kernel bypass.', 'A high-performance streaming runtime designed to eliminate GC pauses. Built on lock-free memory ring buffers, Linux io_uring kernel bypass, and SIMD batch parsers.', 'Distributed Runtimes', 'active', 'https://hyperion.ragetech.dev', 'https://github.com/ragetech/hyperion', 'Rust, Tokio, io_uring, SIMD', 'Spec', 'https://github.com/ragetech/hyperion', 'https://images.unsplash.com/photo-1558494949-ef010cbdcc31?auto=format&fit=crop&w=1200&q=80', '{"throughput": "1.42M events/sec / core", "latency": "0.24ms", "memory": "< 16 MB RSS baseline"}', 1, 1),
('proj-02', 'pulseos', 'PulseOS KV', 'Distributed key-value store engineered for sovereign edge clusters. Combines Raft consensus with eBPF network acceleration.', 'Distributed key-value store engineered for sovereign edge clusters. Combines Raft consensus with eBPF network acceleration and RocksDB persistent storage.', 'Distributed Runtimes', 'active', 'https://pulseos.ragetech.dev', 'https://github.com/ragetech/pulseos', 'Go, Raft, eBPF, RocksDB', 'Spec', 'https://github.com/ragetech/pulseos', 'https://images.unsplash.com/photo-1544197150-b99a580bb7a8?auto=format&fit=crop&w=1200&q=80', '{"consensus": "Multi-Raft v2", "cold_boot": "12ms"}', 1, 2),
('proj-03', 'chimera', 'Chimera Runtime', 'Deterministic multi-agent execution kernel. Coordinates asynchronous cognitive workflows with verified memory checkpoints.', 'Deterministic multi-agent execution kernel. Coordinates asynchronous cognitive workflows with verified memory checkpoints and vector cache.', 'Compilers', 'active', 'https://chimera.ragetech.dev', 'https://github.com/ragetech/chimera', 'Python, PyTorch, CUDA, gRPC', 'Spec', 'https://github.com/ragetech/chimera', 'https://images.unsplash.com/photo-1526374965328-7f61d4dc18c5?auto=format&fit=crop&w=1200&q=80', '{"execution": "DAG rewind", "vector_cache": "2M tokens"}', 1, 3),
('proj-04', 'eclipse', 'Eclipse UI', 'High-density design token system and zero-runtime component foundation engineered for complex developer tools and monitoring suites.', 'High-density design token system and zero-runtime component foundation engineered for complex developer tools and monitoring suites.', 'Kernel & Systems', 'active', 'https://eclipse.ragetech.dev', 'https://github.com/ragetech/eclipse-ui', 'Vanilla CSS, PostCSS, TypeScript', 'Spec', 'https://github.com/ragetech/eclipse-ui', 'https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=1200&q=80', '{"bundle_size": "0 KB", "tokens": "OKLCH"}', 1, 4),
('proj-05', 'vortex', 'Vortex Scheduler', 'Sub-millisecond job scheduling daemon for heterogeneous compute workloads. Replaces heavy distributed cron engines.', 'Sub-millisecond job scheduling daemon for heterogeneous compute workloads. Replaces heavy distributed cron engines.', 'Kernel & Systems', 'active', 'https://vortex.ragetech.dev', 'https://github.com/ragetech/vortex', 'Rust, Tokio, WASM, RocksDB', 'Spec', 'https://github.com/ragetech/vortex', 'https://images.unsplash.com/photo-1563986768609-322da13575f3?auto=format&fit=crop&w=1200&q=80', '{"dispatch": "10us", "capacity": "10M timers"}', 1, 5),
('proj-06', 'aether', 'Aether P2P', 'P2P collaborative CRDT sync mesh for browser and native applications. Converges distributed states without central servers.', 'P2P collaborative CRDT sync mesh for browser and native applications. Converges distributed states without central servers.', 'Distributed Runtimes', 'active', 'https://aether.ragetech.dev', 'https://github.com/ragetech/aether', 'Rust, WASM, WebRTC, CRDT', 'Spec', 'https://github.com/ragetech/aether', 'https://images.unsplash.com/photo-1550751827-4bd374c3f58b?auto=format&fit=crop&w=1200&q=80', '{"latency": "< 8ms", "crdt": "Automerge"}', 1, 6);
INSERT INTO project_sections (id, project_id, section_title, section_content, sort_order) VALUES
('sec-01', 'proj-01', '1. Abstract & Motivation', 'Modern streaming distributed brokers suffer from Java Virtual Machine garbage-collection pauses, multi-megabyte buffer footprints, and kernel-space context switching overhead. Hyperion re-engineers event streaming from the silicon up, pairing Linux io_uring ring buffers with cache-coherent lock-free memory rings in pure, memory-safe Rust.', 1),
('sec-02', 'proj-01', '2. Lock-Free Memory Rings & io_uring', 'Hyperion maps consumer ring buffers directly into shared physical pages. By bypassing standard BSD socket syscalls and processing messages in SIMD batches, Hyperion delivers predictable sub-millisecond tail latencies under multi-gigabit workloads.', 2),
('sec-03', 'proj-02', '1. Edge Storage Consensus', 'PulseOS KV is built for sovereign edge clusters where nodes experience intermittent network partitions. By combining a hardened Multi-Raft protocol with in-kernel eBPF socket filters, read commands bypass user space entirely when state is provably stable.', 1),
('sec-04', 'proj-02', '2. Fast Failover and Zero Partition Drift', 'State persistence is backed by custom RocksDB block tables tuned for solid-state flash memory wear leveling.', 2),
('sec-05', 'proj-03', '1. Deterministic Multi-Agent Coordination', 'Asynchronous cognitive workflows frequently collapse when downstream LLM agents hallucinate or fail structural schema assertions. Chimera Runtime introduces a formal directed acyclic graph (DAG) scheduler with reversible state checkpoints.', 1),
('sec-06', 'proj-03', '2. Memory-Mapped Vector Cache', 'A 2-million token shared memory arena allows multiple worker processes to inspect the same inference context without duplication or serialization overhead.', 2),
('sec-07', 'proj-04', '1. Zero-Runtime Design Architecture', 'Heavy frontend component frameworks introduce megabytes of JavaScript dependencies that slow down systems consoles. Eclipse UI relies entirely on CSS custom properties, modern pseudo-classes, and accessible headless web primitives.', 1),
('sec-08', 'proj-04', '2. High-Density Observability', 'Designed specifically for systems engineers who require maximum information density, monospace data alignment, and microsecond responsiveness.', 2),
('sec-09', 'proj-05', '1. Precision Event Dispatch', 'Standard distributed cron solutions query database tables every minute, creating thundering herd spikes and latency jitter. Vortex Scheduler utilizes hierarchical timing wheels with 10-microsecond dispatch resolution.', 1),
('sec-10', 'proj-05', '2. High-Capacity Timer Arenas', 'Supports up to 10 million active timers per instance with Raft-synchronized failover under 50 milliseconds.', 2),
('sec-11', 'proj-06', '1. Serverless Peer-to-Peer Convergence', 'Aether P2P enables local-first collaborative software where client nodes synchronize document state across encrypted WebRTC data channels with zero server intermediaries.', 1),
('sec-12', 'proj-06', '2. Automerge CRDT & Libp2p Discovery', 'State mutations are recorded in compact vector clocks that guarantee mathematical convergence across concurrent offline edits.', 2);
